import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getT72Detail } from "../../../services/T72Service";
import T72FormModal from "./components/T72FormModal";
import T72IssueModal from "./components/T72IssueModal";
import T72RemarkModal from "./components/T72RemarkModal";
import T72StatusBadge from "./components/T72StatusBadge";

export default function T72DetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIssueModal, setShowIssueModal] = useState(false);
  const [showRemarkModal, setShowRemarkModal] = useState(false);

  const loadData = () => {
    getT72Detail(id).then((res) => {
      setData(res.data);
    });
  };

  useEffect(() => {
    loadData();
  }, [id]);

  if (!data) return <div>Loading...</div>;

  return (
    <div className="container-fluid">
      <div className="row">
        {/* Left Side: T-72 Details */}
        <div className="col-xl-6">
          <div className="card">
            <div className="card-header d-flex justify-content-between align-items-center">
              <div className="d-flex align-items-center">
                <button
                  type="button"
                  className="btn btn-outline-primary btn-sm rounded-circle me-2"
                  style={{ padding: "5px 9px" }}
                  onClick={() => navigate("/t72-purchase")}
                >
                  <i className="fa-solid fa-arrow-left"></i>
                </button>
                <h4 className="mb-0">T-72 Details</h4>
              </div>
              <div>
                {data.status === "RECEIVED" && (
                  <button
                    className="btn btn-warning btn-sm"
                    onClick={() => setShowEditModal(true)}
                  >
                    <i className="fa-solid fa-pen me-2"></i>Edit
                  </button>
                )}
              </div>
            </div>
            <div className="card-body">
              <div className="row">
                <div className="col-lg-6 col-md-12 mb-3">
                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Receive Date:</span>
                    <span className="text-dark">{data.receive_date}</span>
                  </div>

                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Daybook No:</span>
                    <span className="text-dark">{data.daybook_number}</span>
                  </div>

                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Order No:</span>
                    <span className="text-dark">{data.order_number}</span>
                  </div>
                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Challan No:</span>
                    <span className="text-dark">
                      {data.challan_number || "-"}
                    </span>
                  </div>

                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Party Name:</span>
                    <span className="text-dark">{data.party_name}</span>
                  </div>
                </div>

                <div className="col-lg-6 col-md-12 mb-3">
                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Used Area:</span>
                    <span className="text-dark">{data.used_area || "-"}</span>
                  </div>
                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Authorized By:</span>
                    <span className="text-dark">
                      {data.authorized_by ? data.authorized_by.label : "-"}
                    </span>
                  </div>
                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Created By:</span>
                    <span className="text-dark">
                      {data.created_by ? data.created_by.label : "-"}
                    </span>
                  </div>
                  <div className="d-flex justify-content-between mb-2 border-bottom pb-1">
                    <span className="fw-bold text-muted">Status:</span>
                    <T72StatusBadge status={data.status} />
                  </div>
                </div>
              </div>

              <div className="row mt-2">
                <div className="col-12">
                  <div className="d-flex justify-content-between align-items-center mb-2">
                    <h6 className="text-secondary mb-0">Remarks</h6>
                    <button
                      className="btn btn-xs btn-outline-secondary"
                      onClick={() => setShowRemarkModal(true)}
                      title="Edit Remarks"
                    >
                      <i className="fa-solid fa-pen fa-xs pt-1"></i> Edit
                      Remarks
                    </button>
                  </div>
                  <div
                    className="p-3 border rounded bg-warning-light text-dark"
                    style={{ minHeight: "60px" }}
                  >
                    {data.remarks || "No remarks provided."}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Item Details */}
        <div className="col-xl-6">
          <div className="card">
            <div className="card-header d-flex justify-content-between align-items-center">
              <div className="">
                <h5 className="card-title mb-0">Item Details</h5>
              </div>
              <div className="d-flex gap-2">
                {data.status !== "RECEIVED" && (
                  <button
                    className="btn btn-outline-secondary btn-sm"
                    onClick={() =>
                      navigate(`/t72-issued-history?t72_order_id=${data.id}`)
                    }
                  >
                    <i className="fa-solid fa-clock-rotate-left me-2"></i>
                    History
                  </button>
                )}
                {data.status !== "ISSUED" && (
                  <button
                    className="btn btn-danger btn-sm"
                    onClick={() => setShowIssueModal(true)}
                  >
                    <i className="fa-solid fa-share-from-square me-2"></i>Issue
                    Items
                  </button>
                )}
              </div>
            </div>
            <div className="card-body p-0">
              <div className="table-responsive">
                <table className="table table-striped mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>SL No</th>
                      <th>Item Name</th>
                      <th>Qty</th>
                      <th>Unit</th>
                      <th>Location</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.items.map((item, idx) => (
                      <tr key={idx}>
                        <td>{idx + 1}</td>
                        <td>{item.item_name}</td>
                        <td>
                          <span className="fw-bold">
                            {Number(item.available_quantity)}
                          </span>
                          /{Number(item.quantity)}
                        </td>
                        <td>{item.unit}</td>
                        <td>{item.location}</td>
                      </tr>
                    ))}
                    {data.items.length === 0 && (
                      <tr>
                        <td colSpan="5" className="text-center">
                          No Items Found
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>

      <T72FormModal
        show={showEditModal}
        onHide={() => setShowEditModal(false)}
        editData={data}
        reload={loadData}
      />

      <T72IssueModal
        show={showIssueModal}
        onHide={() => setShowIssueModal(false)}
        issueData={data}
        reload={loadData}
      />

      <T72RemarkModal
        show={showRemarkModal}
        onHide={() => setShowRemarkModal(false)}
        t72Id={data.id}
        currentRemarks={data.remarks}
        reload={loadData}
      />
    </div>
  );
}
