import React, { useState, useEffect, useRef } from 'react';
import { getStockByBarcode, stockOutProduct } from '../../../services/ProductService';
import { searchEmployee, searchPurpose, searchSource } from '../../../services/RackService';
import { createEmployee } from '../../../services/OtherService';
import { Modal, Spinner, Form } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { useDispatch, connect } from 'react-redux';
import { toggleStockoutModal, setScanBarcode, updateStockKey } from '../../../store/actions/AuthActions';
import { createSource } from '../../../services/OtherService';
import CreatableSelect from 'react-select/creatable'
import Select from 'react-select'
import RequisitionStockOut from './RequisitionStockOut';

function StockOutBtn({ modalOpen, scanBarcode, user, userPermission }) {
  const emptyStock = {
    stock_id: '',
    barcode_no: '',
    select_quantity: '',
    net_quantity: '',
    product: '',
    ucs_code: '',
    product_net_quantity: '',
    rack: '',
    employee: null,
    purpose: null,
    showRmConf: false
  }
  const STOCKOUT_TYPE_CHOICE = ["MATERIAL CONSUMPTION", "RETURN BORROWED MATERIAL", "LENDING MATERIAL", "REQUISITION"]

  const dispatch = useDispatch()
  const requisitionFormRef = useRef(null);

  const [isSubmitLoading, setIsSubmitLoading] = useState(false)
  const [stock, setStock] = useState([emptyStock])

  const [empModalOpen, setEmpModalOpen] = useState(false)
  const [isEmpSubmitLoading, setIsEmpSubmitLoading] = useState(false)
  const [empForm, setEmpForm] = useState({ name: '', personnel_number: '', phone: '' });
  const [stockIndex, setStockIndex] = useState(0); // for create employee to add employee data
  const [purposeOption, setPurposeOption] = useState([])
  const [optionsEmployee, setOptionsEmployee] = useState([])
  const [isEmployeeFetching, setIsEmployeeFetching] = useState(false)
  const [isPurposeFetching, setIsPurposeFetching] = useState(false)
  const [sourceOption, setSourceOption] = useState([])
  const [isSourceLoading, setIsSourceLoading] = useState(false)
  const [stockoutType, setStockoutType] = useState(STOCKOUT_TYPE_CHOICE[0])

  const [oldestStock, setOldestStock] = useState({ isModalOpen: false, stock: null })

  const [sourceModalOpen, setSourceModalOpen] = useState(false)
  const [newSourceIndexName, setNewSourceIndexName] = useState({ index: 0, sourceName: "" }); // for create source to add source data


  useEffect(() => {
    const handleDefaultBarcodeScan = async () => {
      try {
        const response = await getStockByBarcode({ barcode: scanBarcode });
        const { data } = response.data
        const stockinfo = { barcode_no: scanBarcode, stock_id: data.id, select_quantity: data.quantity, net_quantity: data.quantity, product: data.product, rack: data.rack, ucs_code: data.ucs_code, product_net_quantity: data.product_net_quantity }
        const newStock = { ...emptyStock, ...stockinfo }
        setStockoutType(STOCKOUT_TYPE_CHOICE[1])
        setStock([newStock]);
      } catch (error) {
        toast.error(error.response.data.message)
      } finally {
        dispatch(setScanBarcode(null))
      }
    };

    if (scanBarcode && modalOpen) {
      handleDefaultBarcodeScan()
      fetchEmployeeOptions()
      fetchPurposeOptions()

    }
    if (modalOpen) {
      setStockoutType(STOCKOUT_TYPE_CHOICE[0])
    }
  }, [scanBarcode, modalOpen])


  const toggleEmpModal = () => {
    if (empModalOpen) {
      setEmpForm({ name: '', personnel_number: '', phone: '' })
    }
    setEmpModalOpen(!empModalOpen)
  }

  const toggleOldestStockModal = () => {
    if (oldestStock.isModalOpen) {
      setOldestStock({ isModalOpen: false, stock: null })
    } else {
      setOldestStock({ isModalOpen: false, ...oldestStock })
    }
  }

  const handleChangeEmpInput = (e) => {
    const { name, value } = e.target
    setEmpForm({ ...empForm, [name]: value })
  }

  const handleEmpSubmit = async (e) => {
    e.preventDefault()
    try {
      if (!isEmpSubmitLoading) {
        setIsEmpSubmitLoading(true)
        const resp = await createEmployee(empForm)
        const resp_data = resp.data.data
        const empOption = { value: resp_data.id, label: `${resp_data.name} (${resp_data.personnel_number})` }
        setOptionsEmployee([empOption, ...optionsEmployee])
        let newStock = [...stock]
        newStock[stockIndex] = { ...newStock[stockIndex], employee: empOption }
        setStock([...newStock]);
        toast.success(resp.data.message)
        setIsEmpSubmitLoading(false)
        toggleEmpModal()
      }
    } catch (error) {
      toast.error(error.response.data.message)
    };
  }

  const toggleModal = () => {
    if (modalOpen) {
      setStock([emptyStock])
      setPurposeOption([])
      setOptionsEmployee([])
      setStockoutType(STOCKOUT_TYPE_CHOICE[0])
    } else {
      fetchEmployeeOptions()
      fetchPurposeOptions()
    }
    dispatch(toggleStockoutModal())
  }

  const handleBarcodeChange = (value, index) => {
    let newStock = [...stock]
    newStock[index] = { ...newStock[index], barcode_no: value, stock_id: '' }
    setStock([...newStock]);
  };

  const handleQuantityChange = (value, index) => {
    const elem = document.getElementById(`select_quantity-${index}`)
    let newStock = [...stock]
    const min = 1; // Set your minimum value here
    const max = newStock[index].net_quantity; // Set your maximum value here
    // Check if the input is within the specified range
    if (value === '' || (value >= min && value <= max)) {
      newStock[index] = { ...newStock[index], select_quantity: value }
      setStock([...newStock]);
      elem?.classList.remove('is-invalid')
    } else {
      elem?.classList.add('is-invalid')
    }
  };

  const hasDuplicatesStock = () => {
    const idSet = new Set();
    for (const s of stock) {
      if (idSet.has(s.barcode_no)) {
        return true; // Found a duplicate id
      }
      idSet.add(s.barcode_no);
    }
    return false; // No duplicates found
  };

  const handleKeyPress = async (e, index) => {
    if (e.key === 'Enter' && e.target.value.length > 0) {
      if (hasDuplicatesStock()) {
        toast.error("Barcode already exists in stock OUT list")
      } else {
        try {
          const queryParams = {
            barcode: e.target.value,
            older_stock_id: stock.filter((_, ind) => index !== ind).map(item => item.stock_id)
          }
          const response = await getStockByBarcode(queryParams);
          const { data } = response.data
          let newStock = [...stock]
          newStock[index] = { ...newStock[index], stock_id: data.id, select_quantity: data.quantity, net_quantity: data.quantity, product: data.product, ucs_code: data.ucs_code, product_net_quantity: data.product_net_quantity, rack: data.rack }
          setStock([...newStock]);
          if (data?.oldest_stock) {
            setOldestStock({ isModalOpen: true, stock: data?.oldest_stock, index: index })
          }
          document.getElementById(`barcode_no-${index}`)?.classList.remove('is-invalid')
        } catch (error) {
          console.log("error", error)
          toast.error(error?.response?.data?.message)
          document.getElementById(`barcode_no-${index}`)?.classList.add('is-invalid')
        }
      }
    }
  };

  const handleContinueWithOldStock = () => {
    const index = oldestStock?.index
    const data = oldestStock?.stock
    let newStock = [...stock]
    newStock[index] = { ...newStock[index], stock_id: data.id, select_quantity: data.quantity, net_quantity: data.quantity, barcode_no: data.barcode }
    setStock([...newStock]);
    toggleOldestStockModal()
  }

  const validateStocks = () => {
    const validList = ['stock_id', 'barcode_no', 'select_quantity']
    if (["RETURN BORROWED MATERIAL", "LENDING MATERIAL"].includes(stockoutType)) {
      validList.push('source')
    } else {
      validList.push('purpose')
    }
    if (!(user?.role === "User" && userPermission?.consumption_stockout)) {
      validList.push("employee")
    }
    return stock.map((item, index) => {
      return Object.entries(item).map(([key, value]) => {
        if (validList.includes(key)) {
          if (value === null || value.length === 0) {
            const elem = document.getElementById(`${key === "stock_id" ? "barcode_no" : key}-${index}`)
            if (elem) {
              elem.classList.add('is-invalid')
              elem.focus()
            }
            return false
          }
          return true
        }
        return true
      }).every(val => val === true)

    })
  }

  const formatEmptyStock = (stockouttype) => {
    if (stockouttype === "RETURN BORROWED MATERIAL") {
      const { purpose, ...rest } = emptyStock
      return { ...rest, source: "" }
    }
    return emptyStock
  }


  const addStock = () => {
    if (validateStocks().every(value => value === true)) {
      setStock(stock.concat(formatEmptyStock(stockoutType)))
    }
  }

  const removeStock = (index) => {
    const newStock = [...stock]
    newStock.splice(index, 1)
    setStock([...newStock])
  }

  const removeConfirm = (index, toggleVal) => {
    const newStock = [...stock]
    newStock[index] = { ...newStock[index], showRmConf: toggleVal }
    setStock([...newStock])
  }

  const handleStockoutType = (e) => {
    if (user?.role === "User" && userPermission?.consumption_stockout) {
      return
    }
    const { value } = e.target
    setStockoutType(value)
    if (["RETURN BORROWED MATERIAL", "LENDING MATERIAL"].includes(value)) {
      fetchSourceOptions(value)
    }
    setStock([formatEmptyStock(value)])
  }

  const onSubmitStockOUT = () => {
    if (!isSubmitLoading) {
      if (stockoutType === "REQUISITION") {
        requisitionFormRef.current.submit();
        return;
      }

      if (validateStocks().every(value => value === true)) {
        const data = stock
          .filter(item => item.select_quantity > 0 && item.select_quantity <= item.net_quantity)
          .map(st => {
            return {
              stock_id: st.stock_id,
              select_quantity: Number(st.select_quantity),
              ...(!(user?.role === "User" && userPermission?.consumption_stockout) && { employee_id: st.employee.value }),
              ...(["RETURN BORROWED MATERIAL", "LENDING MATERIAL"].includes(stockoutType)
                ? { source: st.source.value }
                : { purpose: st.purpose.value })
            };
          });
        setIsSubmitLoading(true)
        stockOutProduct({ stock_list: data, stockout_type: stockoutType }).then((response) => {
          toast.success(response.data.message)
          toggleModal()
          dispatch(updateStockKey())
        }).catch((error) => {
          toast.error(error.response.data.message)
        }).finally(() => {
          setIsSubmitLoading(false)
        });
      }
    }
  }

  const LoadingIndicator = () => {
    return (
      <Spinner color='primary' size={'sm'} delay={0} />
    )
  }

  async function fetchEmployeeOptions() {
    try {
      setIsEmployeeFetching(true)
      const resp = await searchEmployee()
      setOptionsEmployee(resp.data.data);
    }
    catch (error) {
      console.log("EROR =>", error)
    } finally {
      setIsEmployeeFetching(false)
    }
  };

  async function fetchPurposeOptions() {
    try {
      setIsPurposeFetching(true)
      const resp = await searchPurpose()
      setPurposeOption(resp.data.data);
    }
    catch (error) {
      console.log("EROR =>", error)
    } finally {
      setIsPurposeFetching(false)
    }
  };

  async function fetchSourceOptions(stokcintype) {
    try {
      setIsSourceLoading(true)
      const resp = await searchSource({ stock_type: stokcintype })
      setSourceOption(resp.data.data)
    }
    catch (error) {
      console.log("ERROR => ", error)
    } finally {
      setIsSourceLoading(false)
    }
  };

  const handlePurposeChange = (data, index) => {
    try {
      let newStock = [...stock]
      newStock[index] = { ...newStock[index], purpose: { value: data.value, label: data.label } }
      setStock([...newStock]);
      document.getElementById(`purpose-${index}`)?.classList.remove('is-invalid')
    } catch (error) {
      console.log(error.response.data.message)
    }
  }

  const handleEmployeeChange = (data, index) => {
    try {
      let newStock = [...stock]
      if (data.__isNew__) {
        setStockIndex(index)
        toggleEmpModal()
        setEmpForm({ ...empForm, name: data.value })
        newStock[index] = { ...newStock[index], employeeInput: '' }
      } else {
        newStock[index] = { ...newStock[index], employee: { value: data.value, label: data.label } }
      }
      setStock([...newStock]);
      document.getElementById(`employee-${index}`)?.classList.remove('is-invalid')
    } catch (error) {
      console.log(error.response.data.message)
    }
  }

  const handleSourceChange = (data, index) => {
    try {
      let newStock = [...stock]
      newStock[index] = { ...newStock[index], source: { value: data.value, label: data.label } }
      setStock([...newStock]);
      document.getElementById(`source-${index}`)?.classList.remove('is-invalid')
    } catch (error) {
      console.log(error.response.data.message)
    }
  }

  const toggleSourceModal = () => {
    if (sourceModalOpen) {
      setNewSourceIndexName({ index: 0, sourceName: "" })
    }
    setSourceModalOpen(!sourceModalOpen)
  }

  const handleBorrowSourceChange = (data, index) => {
    try {
      if (data.__isNew__) {
        setNewSourceIndexName({ sourceName: data.value, index })
        toggleSourceModal()
      } else {
        const newStock = [...stock]
        newStock[index] = { ...newStock[index], source: { value: data.value, label: data.label } }
        setStock([...newStock]);
        document.getElementById(`employee-${index}`)?.classList.remove('is-invalid')
      }
    } catch (error) {
      console.log(error.response.data.message)
    }
  }

  const handleSubmitSource = async (e) => {
    e.preventDefault()
    const { index, sourceName } = newSourceIndexName
    createSource({ name: sourceName, central_store: false }).then((resp) => {
      const { data, message } = resp.data
      const newOption = { value: data.value, label: data.label }
      setSourceOption([...sourceOption, newOption])
      let newStock = [...stock]
      newStock[index] = { ...newStock[index], source: newOption }
      setStock([...newStock]);
      toast.success(message)
      toggleSourceModal()
    }).catch((error) => {
      console.log("error", error)
      toast.error(error.response.data.message)
    });
  }

  return (
    <>
      <button className="btn btn-danger mx-2" onClick={toggleModal}> Stock OUT <i className="fa-solid fa-square-up-right ms-2"></i> </button>
      {/* stock out modal */}

      <Modal className="modal fade" id="exampleModal3"
        show={modalOpen}
        onHide={toggleModal}
        fullscreen={true}
        backdrop="static"
        keyboard={false} >
        <div className="modal-content">
          <div className="modal-header bg-danger">
            <h3 className="modal-title text-white">Stock OUT</h3>
            <button type="button" className="btn btn-secondary light btn-sm" onClick={toggleModal}>
              <i className="fa-solid  fa-lg fa-xmark"></i>
            </button>
          </div>
          <div className="modal-body">
            <div className="mb-3">
              <label className='form-label fw-bold me-3'>Stock Out Type:</label>
              {STOCKOUT_TYPE_CHOICE.map(item => (
                <div className="form-check custom-checkbox mb-2 form-check-inline" key={item}>
                  <input type="radio"
                    className="form-check-input"
                    checked={stockoutType === item}
                    id={item}
                    name="stockoutType"
                    value={item}
                    disabled={user?.role === "User" && userPermission?.consumption_stockout && item !== "MATERIAL CONSUMPTION"}
                    onChange={handleStockoutType} />
                  <label className="form-check-label" htmlFor={item}>{item}</label>
                </div>
              ))}
            </div>
            {stockoutType === "REQUISITION" ? <RequisitionStockOut
              ref={requisitionFormRef}
              toggleModal={toggleModal}
              setIsSubmitLoading={setIsSubmitLoading}
            /> :
              (
                <div className='table-responsive active-projects' style={{ minHeight: '80vh' }}>
                  <div id="employee-tbl_wrapper" className="dataTables_wrapper active-projects no-footer">
                    <table id="empoloyees-tblwrapper" className="table table-striped ItemsCheckboxSec dataTable no-footer mb-0">
                      <thead>
                        <tr>
                          <th>Barcode</th>
                          <th>Quantity</th>
                          <th>Material</th>
                          <th>Employee</th>
                          <th>{stockoutType === "MATERIAL CONSUMPTION" ? "Purpose" : "Source"}</th>
                          <th>Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {stock.map((item, index) => (
                          <tr key={index}>
                            <td>
                              <div className='d-flex align-items-center gap-2'>
                                <input type="text"
                                  id={`barcode_no-${index}`}
                                  style={{ width: '10rem' }}
                                  autoFocus={item.barcode_no.length === 0}
                                  value={item.barcode_no}
                                  onChange={(e) => { handleBarcodeChange(e.target.value, index) }}
                                  onKeyPress={(e) => { handleKeyPress(e, index) }}
                                  className="form-control" placeholder="Barcode" />
                                {item.stock_id ? (
                                  <span className='d-flex flex-column'>
                                    <span className='text-primary me-2'>
                                      Rack
                                    </span>
                                    <small className='px-2 text-bg-light border border-light rounded-2'>
                                      {item.rack}
                                    </small>
                                  </span>
                                ) : null}
                              </div>
                            </td>
                            {item.stock_id ? (<>
                              <td>
                                <div className='input-group' style={{ minWidth: '8rem', maxWidth: '10rem' }}>
                                  <input type="number"
                                    min={1}
                                    max={item.net_quantity}
                                    autoFocus={true}
                                    onChange={(e) => { handleQuantityChange(e.target.value, index) }}
                                    value={item.select_quantity}
                                    className="form-control" id={`select_quantity-${index}`} placeholder="Quantity" />
                                  <span className="input-group-text">{item.net_quantity}</span>
                                </div>
                              </td>
                              <td>
                                <div className='d-flex flex-column'>
                                  <span className='text-primary'>{item.product} <span>
                                    <small className='px-2 text-bg-light border border-light rounded-2'>
                                      <span className='text-primary me-1'>
                                        NQ:
                                      </span>
                                      {item.product_net_quantity}
                                    </small>
                                  </span>
                                  </span>
                                  <span className=''>
                                    {item.ucs_code}
                                  </span>
                                </div>
                              </td>
                              <td>
                                {user?.role === "User" && userPermission?.consumption_stockout ? user?.name :
                                  <div style={{ width: '18rem' }}>
                                    <CreatableSelect
                                      value={item.employee}
                                      onChange={(data) => handleEmployeeChange(data, index)}
                                      placeholder={"Select Employee"}
                                      isClearable={false}
                                      isLoading={isEmployeeFetching}
                                      options={optionsEmployee}
                                      id={`employee-${index}`}
                                      className='react-select'
                                      classNamePrefix='select'
                                    />
                                  </div>
                                }
                              </td>
                              <td>
                                <div style={{ width: '12rem' }}>
                                  {stockoutType === "MATERIAL CONSUMPTION" ?
                                    <CreatableSelect
                                      isClearable={false}
                                      id={`purpose-${index}`}
                                      value={item.purpose}
                                      className='react-select'
                                      classNamePrefix='select'
                                      placeholder="Select Purpose"
                                      options={purposeOption}
                                      isLoading={isPurposeFetching}
                                      onChange={(data) => { handlePurposeChange(data, index) }}
                                      components={{ LoadingIndicator }}
                                    />
                                    : stockoutType === "LENDING MATERIAL" ?
                                      <CreatableSelect
                                        isClearable={false}
                                        id={`source-${index}`}
                                        value={item.source}
                                        className='react-select'
                                        classNamePrefix='select'
                                        placeholder="Search Source"
                                        options={sourceOption}
                                        isLoading={isSourceLoading}
                                        onChange={(data) => { handleBorrowSourceChange(data, index) }}
                                        components={{ LoadingIndicator }}
                                        styles={
                                          {
                                            container: (provided) => ({
                                              ...provided,
                                              width: '15rem', // Set the width of the select container
                                            }),
                                          }
                                        }
                                      /> : <Select
                                        isClearable={false}
                                        id={`source-${index}`}
                                        value={item.source}
                                        className='react-select'
                                        classNamePrefix='select'
                                        placeholder="Search Source"
                                        options={sourceOption}
                                        isLoading={isSourceLoading}
                                        onChange={(data) => { handleSourceChange(data, index) }}
                                        components={{ LoadingIndicator }}
                                        styles={
                                          {
                                            container: (provided) => ({
                                              ...provided,
                                              width: '15rem', // Set the width of the select container
                                            }),
                                          }
                                        }
                                      />}
                                </div>
                              </td>
                            </>) : (<>
                              <td></td>
                              <td></td>
                              <td></td>
                              <td></td>
                            </>)}
                            <td>
                              {item.stock_id.length && (stock.length === index + 1) && !item.showRmConf ? (
                                <button className='btn btn-sm me-2 btn-outline-success rounded' onClick={addStock}><i className="fa-solid fa-lg fa-plus"></i></button>
                              ) : null}
                              {stock.length > 1 ? item.showRmConf ? (
                                <div className="d-flex align-items-center flex-column bg-light p-2 rounded">
                                  <h6>Confirm Remove</h6>
                                  <div className='d-flex justify-content-around align-items-center'>
                                    <span className='c-pointer badge badge-outline-success badge-sm'
                                      onClick={() => removeStock(index)}>
                                      <i class="fa-solid fa-check"></i>
                                    </span>
                                    <span className='c-pointer badge badge-outline-danger badge-sm ms-3'
                                      onClick={() => removeConfirm(index, false)}>
                                      <i class="fa-solid fa-xmark"></i>
                                    </span>
                                  </div>
                                </div>
                              ) : (
                                <button className='btn btn-sm btn-outline-danger rounded'
                                  onClick={() => {
                                    item.stock_id.length > 0 ? removeConfirm(index, true) : removeStock(index)
                                  }}>
                                  <i className="fa-solid fa-trash"></i>
                                </button>
                              ) : null}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

          </div>
          <div className="modal-footer">
            <button type="submit" className="btn btn-primary btn-sm" disabled={isSubmitLoading} onClick={onSubmitStockOUT}>
              {isSubmitLoading ? (<>
                <LoadingIndicator /> Stock OUT
              </>) : "Stock OUT"}
            </button>
            <button type="button" className="btn btn-danger light btn-sm" disabled={isSubmitLoading} onClick={toggleModal}>Close</button>
          </div>
        </div>
      </Modal>

      {/* create emplppyee modal */}
      <Modal className="modal  fade" id="exampleModal3"
        show={empModalOpen}
        onHide={toggleEmpModal}
        backdrop="static"
        keyboard={false} >
        <div className="modal-content modal-sm">
          <div className="modal-header ">
            <h3 className="modal-title">Create Employee</h3>
            <button type="button" className="btn btn-danger light btn-sm" onClick={toggleEmpModal}>
              <i className="fa-solid  fa-lg fa-xmark"></i>
            </button>
          </div>
          <div className="modal-body">
            <Form onSubmit={(e) => handleEmpSubmit(e)}>
              <div className="row">
                <div className="col-xl-12">
                  <div className="mb-3">
                    <label htmlFor="name" className="form-label">Employee Name <span className="text-danger">*</span></label>
                    <input type="text" autoFocus className="form-control" id="name" placeholder="Enter Name"
                      value={empForm.name} name='name' onChange={handleChangeEmpInput} required />
                  </div>
                  <div className="mb-3">
                    <label htmlFor="personnel_number" className="form-label">Personnel Number <span className="text-light">(Optional)</span></label>
                    <input type="number" className="form-control" id="personnel_number" placeholder="Enter personnel number"
                      value={empForm.personnel_number} name='personnel_number' onChange={handleChangeEmpInput} />
                  </div>

                  <div className="mb-3">
                    <label htmlFor="phone" className="form-label">Mobile Number <span className="text-light">(Optional)</span></label>
                    <input type="number"
                      className="form-control"
                      id="phone"
                      placeholder="Enter Mobile Number"
                      value={empForm.phone}
                      name='phone'
                      onChange={handleChangeEmpInput} />
                  </div>
                </div>
              </div>
              <div>
                <button type="submit" className="btn btn-primary me-1" disabled={isEmpSubmitLoading}>
                  {isEmpSubmitLoading ? (<>
                    <LoadingIndicator /> Create
                  </>) : "create"}
                </button>
                <button type="button" disabled={isEmpSubmitLoading} onClick={() => toggleEmpModal()} className="btn btn-danger light ms-1">Cancel</button>
              </div>
            </Form>
          </div>
        </div>
      </Modal>

      <Modal className="modal fade" id="exampleModal3"
        show={oldestStock.isModalOpen}
        onHide={toggleOldestStockModal}
        backdrop="static"
        keyboard={false} >
        <div className="modal-content bg-warning">
          <div className="modal-body">
            <p className='text-secondary'>
              You have chosen a latest stock. There is an older stock available on Rack {oldestStock.rack} with barcode <strong>{oldestStock?.stock?.barcode}</strong> and quantity <strong>{oldestStock?.stock?.quantity}</strong>.
              <br />
              Please confirm if you want to proceed with this selection or continue with the oldest stock
            </p>
            <div className=' d-flex align-items-center flex-column'>
              <button type="submit" className="btn btn-primary mb-2" onClick={handleContinueWithOldStock}>
                Continue with oldest stock
              </button>
              <button type="button" onClick={toggleOldestStockModal} className="btn btn-outline-secondary light ms-1">
                Proceed with current stock
              </button>
            </div>
          </div>
        </div>
      </Modal>

      {/* create source modal */}
      <Modal className="modal modal-sm fade" id="exampleModal1" show={sourceModalOpen} onHide={toggleSourceModal}>
        <div className="modal-content">
          <div className="modal-header">
            <h1 className="modal-title fs-5" id="exampleModalLabel1">Create New Source</h1>
            <button type="button" className="btn-close" onClick={toggleSourceModal}></button>
          </div>
          <div className="modal-body">
            <form onSubmit={(e) => { handleSubmitSource(e) }} method='POST'>
              <div className="row">
                <div className="col-xl-12">
                  <label className="form-label">Source Name<span className="text-danger">*</span></label>
                  <input type="text"
                    className="form-control mb-3"
                    placeholder="Enter Source Name" required
                    value={newSourceIndexName.sourceName} onChange={(e) => setNewSourceIndexName({ ...newSourceIndexName, sourceName: e.target.value })} />
                </div>
              </div>
              <button type="submit" className="btn btn-block btn-sm btn-primary mt-3 float-end">Submit</button>
            </form>
          </div>
        </div>
      </Modal>
    </>
  )
}

const mapStateToProps = (state) => {
  return {
    modalOpen: state.auth.stockoutModal,
    scanBarcode: state.auth.scanBarcode,
    user: state.auth.user,
    userPermission: state.auth.user?.user_permission
  };
};

export default connect(mapStateToProps)(StockOutBtn);