import { useState, useEffect } from "react";
import { Modal } from "react-bootstrap";
import { updateT72Remarks } from "../../../../services/T72Service";
import { toast } from "react-toastify";

export default function T72RemarkModal({
  show,
  onHide,
  t72Id,
  currentRemarks,
  reload,
}) {
  const [remarks, setRemarks] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (show) {
      setRemarks(currentRemarks || "");
    }
  }, [show, currentRemarks]);

  const submit = async () => {
    setSaving(true);
    try {
      await updateT72Remarks(t72Id, remarks);
      toast.success("Remarks Updated");
      reload();
      onHide();
    } catch (error) {
      console.error(error);
      toast.error("An error occurred while updating remarks");
    } finally {
      setSaving(false);
    }
  };

  if (!show) return null;

  return (
    <Modal show={show} onHide={onHide} centered>
      <div className="modal-content">
        <div className="modal-header bg-primary text-white">
          <h5 className="modal-title text-white">Edit Remarks</h5>
          <button
            type="button"
            className="btn-close btn-close-white"
            onClick={onHide}
          ></button>
        </div>
        <div className="modal-body">
          <div className="mb-3">
            <label className="form-label">Remarks</label>
            <textarea
              className="form-control"
              rows="5"
              value={remarks}
              onChange={(e) => setRemarks(e.target.value)}
              placeholder="Enter remarks..."
            />
          </div>
        </div>
        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onHide}>
            Cancel
          </button>
          <button
            className="btn btn-success"
            onClick={submit}
            disabled={saving}
          >
            {saving ? "Saving..." : "Save Remarks"}
          </button>
        </div>
      </div>
    </Modal>
  );
}
