import React, { useState } from 'react'
import { connect, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom'
import { loadingToggleAction, loginAction } from '../../store/actions/AuthActions';
import { Spinner } from 'react-bootstrap';

import logo from '../../images/logo/logofullv1.png';
import LogoWhite from '../../images/logo/logofull-white.png';
import bg6 from '../../images/background/bg.jpg';

function Login({ showLoading }) {
	const navigate = useNavigate();
	const [personnel_number, setPersonnelNumber] = useState('');
	let errorsObj = { personnel_number: '', password: '' };
	const [errors, setErrors] = useState(errorsObj);
	const [password, setPassword] = useState('');
	const dispatch = useDispatch();

	function onLogin(e) {

		e.preventDefault();
		if (!showLoading) {
			let error = false;
			const errorObj = { ...errorsObj };
			if (personnel_number === '') {
				errorObj.personnel_number = 'Email is Required';
				error = true;
			}
			if (password === '') {
				errorObj.password = 'Password is Required';
				error = true;
			}
			setErrors(errorObj);
			if (error) {
				return;
			}
			dispatch(loadingToggleAction(true));
			dispatch(loginAction(personnel_number, password, navigate));
		}
	}
	return (
		<div className="page-wraper">
			<div className="browse-job login-style3">
				<div className="bg-img-fix overflow-hidden" style={{ background: '#fff url(' + bg6 + ')', height: "100vh", backgroundRepeat: "no-repeat", backgroundSize: "cover" }}>

					<div className="d-flex align-items-center justify-content-end">
						<div id="mCSB_1" className="mCustomScrollBox mCS-light mCSB_vertical mCSB_inside" style={{ maxHeight: "653px" }}>
							<div id="mCSB_1_container" className="mCSB_container" style={{ position: "relative", top: "30px", left: "0", dir: "ltr" }}>
								<div className="login-form style-2">
									<div className="card-body">
										<div style={{ marginBottom: '.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }} >
											<img src={logo} alt="" width={'200px'} className="width-200 light-logo" />
											<img src={LogoWhite} alt="" width={'200px'} className="width-200 dark-logo" />
										</div>
										{process.env?.REACT_APP_CLIENT_LOGIN_PAGE_DESCRIPTION &&
											<h4 className="form-title text-center mb-0 text-primary fw-bold">
												{process.env.REACT_APP_CLIENT_LOGIN_PAGE_DESCRIPTION}
											</h4>
										}
										<div className="nav nav-tabs border-bottom-0" >
											<div className="tab-content w-100" id="nav-tabContent">
												<div className="tab-pane fade active show" id="nav-personal">
													<form className=" dz-form p-4" onSubmit={onLogin}>
														<h3 className="form-title text-center m-t0">Login Your Account</h3>
														<div className="dz-separator-outer mb-4">
															<div className="dz-separator bg-primary style-liner"></div>
														</div>
														<p>Enter your Personnel Number and Password. </p>
														<div className="form-group mb-3">
															<label>Personnel Number or Email</label>
															<input type="text" className="form-control"
																placeholder='Enter Personnel Number or Email'
																value={personnel_number} onChange={(e) => setPersonnelNumber(e.target.value)} />
															{errors.personnel_number && <div className="text-danger fs-12">{errors.personnel_number}</div>}
														</div>
														<div className="form-group mb-3">
															<label>Password</label>
															<input type="password" className="form-control"
																placeholder='Enter Password'
																value={password} onChange={(e) => setPassword(e.target.value)} />
															{errors.password && <div className="text-danger fs-12">{errors.password}</div>}
														</div>

														<button type="submit" disabled={showLoading} className="btn btn-primary btn-block dz-xs-flex mt-4 m-r5">
															{showLoading ? <><Spinner size="sm" /> Login</> : "Login"}</button>
													</form>
												</div>

											</div>
										</div>
									</div>
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>
		</div>
	)
}

const mapStateToProps = (state) => {
	return {
		showLoading: state.auth.showLoading,
	};
};
export default connect(mapStateToProps)(Login);