import React from "react";

const T72StatusBadge = ({ status }) => {
  let badgeClass = "bg-primary-light text-primary"; // Default

  switch (status) {
    case "RECEIVED":
      badgeClass = "bg-success-light text-success";
      break;
    case "PARTIALLY_ISSUED":
      badgeClass = "bg-warning-light text-warning";
      break;
    case "ISSUED":
      badgeClass = "bg-danger-light text-danger";
      break;
    default:
      badgeClass = "bg-secondary-light text-secondary";
  }

  return (
    <span className={`badge badge-sm ${badgeClass}`}>
      {status ? status.replace(/_/g, " ") : "N/A"}
    </span>
  );
};

export default T72StatusBadge;
