import axiosInstance from "./AxiosInstance";

export function getT72List(queryParams = {}) {
  // queryParams expected keys: page, page_size, query, status
  const params = new URLSearchParams();
  if (queryParams.page) params.append("page", queryParams.page);
  if (queryParams.page_size) params.append("page_size", queryParams.page_size);
  if (queryParams.query) params.append("query", queryParams.query);
  if (queryParams.status) params.append("status", queryParams.status);

  return axiosInstance.get(`api/t72/?${params.toString()}`);
}

export function createT72(data) {
  return axiosInstance.post("api/t72/", data);
}

export function updateT72(id, data) {
  return axiosInstance.put(`api/t72/${id}/`, data);
}

export function updateT72Remarks(id, remarks) {
  return axiosInstance.patch(`api/t72/${id}/remarks/`, { remarks });
}

export function getT72Detail(id) {
  return axiosInstance.get(`api/t72/${id}/`);
}


export function issueT72(id, data) {
  return axiosInstance.post(`api/t72/${id}/issue/`, data);
}

/**
 * Dashboard counts
 */
export function getT72Dashboard() {
  return axiosInstance.get("api/t72/dashboard/");
}

export function searchUsers() {
  return axiosInstance.get('api/search/users');
}

export function getT72IssuedHistory(queryParams = {}) {
  const params = new URLSearchParams();
  Object.keys(queryParams).forEach(key => {
    if (queryParams[key]) params.append(key, queryParams[key]);
  });
  return axiosInstance.get(`api/t72/history/?${params.toString()}`);
}

export function exportT72IssuedHistory(queryParams = {}) {
  const params = new URLSearchParams();
  Object.keys(queryParams).forEach(key => {
    if (queryParams[key]) params.append(key, queryParams[key]);
  });
  return axiosInstance.get(`api/t72/history/export/?${params.toString()}`, {
    responseType: 'blob',
  });
}
