// pages/T72IssuedHistory.jsx
import { useEffect, useState } from "react";
import {
  getT72IssuedHistory,
  exportT72IssuedHistory,
} from "../../../services/T72Service";
import DebounceSearchInput from "../../constant/DebounceSearchInput";
import Pagination from "../../constant/Pagination";
import TableLoaderEffect from "../../constant/TableLoader";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import CustomDateRangePicker from "../../constant/CustomDateRangerPicker";
import { Modal } from "react-bootstrap";
import { toast } from "react-toastify";

export default function T72IssuedHistory() {
  const [data, setData] = useState([]);
  const [totals, setTotals] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [params, setParams] = useState({
    page: 1,
    page_size: 10,
    query: "",
    t72_order_id: searchParams.get("t72_order_id") || "",
  });

  // Date Filter State
  const [fromDate, setFromDate] = useState(null);
  const [toDate, setToDate] = useState(null);
  const [selectedPeriod, setSelectedPeriod] = useState("All");

  // Export State
  const [showExportConfirm, setShowExportConfirm] = useState(false);
  const [exporting, setExporting] = useState(false);

  const loadData = async (updatedParams) => {
    setIsLoading(true);
    try {
      const queryParams = { ...(updatedParams || params) };
      if (fromDate) queryParams.from_date = fromDate;
      if (toDate) queryParams.to_date = toDate;

      const listRes = await getT72IssuedHistory(queryParams);
      setData(listRes.data.results || listRes.data.data);
      setTotals(listRes.data.count || listRes.data.total);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    // When date changes, reload with page 1
    const newParams = { ...params, page: 1 };
    setParams(newParams);
    loadData(newParams);
  }, [fromDate, toDate]);

  const handleSearchChange = (value) => {
    const updatedParams = { ...params, query: value, page: 1 };
    setParams(updatedParams);
    loadData(updatedParams);
  };

  const handlePagination = (page) => {
    const newPage = page.selected + 1;
    const updatedParams = { ...params, page: newPage };
    setParams(updatedParams);
    loadData(updatedParams);
  };

  const handleExport = async () => {
    setExporting(true);
    try {
      const queryParams = { ...params };
      delete queryParams.page; // Export all matching query
      delete queryParams.page_size;
      if (fromDate) queryParams.from_date = fromDate;
      if (toDate) queryParams.to_date = toDate;

      const response = await exportT72IssuedHistory(queryParams);

      // Download
      const blob = new Blob([response.data], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      // filename from header or fallback
      const contentDisposition = response.headers["content-disposition"];
      let filename = "T72_Issued_History.xlsx";
      if (contentDisposition) {
        const fileNameMatch = contentDisposition.match(/filename="?(.+)"?/);
        if (fileNameMatch && fileNameMatch.length === 2)
          filename = fileNameMatch[1].replace(/"/g, "");
      }
      link.setAttribute("download", filename);
      document.body.appendChild(link);
      link.click();
      link.remove();
      setShowExportConfirm(false);
      toast.success("Exported Successfully");
    } catch (error) {
      console.error("Export failed", error);
      toast.error("Failed to export");
    } finally {
      setExporting(false);
    }
  };

  return (
    <div className="container-fluid">
      <div className="row">
        <div className="col-xl-12">
          <div className="card">
            <div className="card-body p-0">
              <div className="tbl-caption d-flex justify-content-between text-wrap align-items-center p-3">
                <div className="d-flex align-items-center justify-content-center gap-3">
                  <div>
                    <button
                      type="button"
                      className="btn btn-outline-primary btn-sm rounded-circle"
                      onClick={() => {
                        if (params.t72_order_id) {
                          navigate(`/t72-purchase/${params.t72_order_id}`);
                        } else {
                          navigate("/t72-purchase");
                        }
                      }}
                      title={
                        params.t72_order_id ? "Back to Detail" : "Back to List"
                      }
                    >
                      <i className="fa-solid fa-arrow-left"></i>
                    </button>
                  </div>
                  <div>
                    <h4 className="mb-0">T-72 Issued Item History</h4>
                  </div>
                </div>

                <div className="d-flex align-items-center gap-3">
                  <div>
                    <CustomDateRangePicker
                      fromDate={fromDate}
                      toDate={toDate}
                      selectedPeriod={selectedPeriod}
                      onChange={({ fromDate, toDate, selectedPeriod }) => {
                        setFromDate(fromDate);
                        setToDate(toDate);
                        setSelectedPeriod(selectedPeriod);
                        // Page reset handled in effect
                      }}
                      hideLabel={true}
                      isClearable={true}
                    />
                  </div>
                  <div className="form-group">
                    <DebounceSearchInput
                      handleSearchChange={handleSearchChange}
                      placeholder="Search Item, Order, Employee..."
                    />
                  </div>
                  <div>
                    <button
                      className="btn btn-success"
                      onClick={() => setShowExportConfirm(true)}
                    >
                      <i className="fa-solid fa-file-excel me-1"></i> Export
                    </button>
                  </div>
                </div>
              </div>

              <div className="table-responsive active-projects style-1">
                <table className="table dataTable mb-0">
                  <thead>
                    <tr>
                      <th>Order No</th>
                      <th>Item Name</th>
                      <th>Quantity</th>
                      <th>Unit</th>
                      <th>Issued By</th>
                      <th>Received By</th>
                      <th>Issue Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {isLoading ? (
                      <TableLoaderEffect colLength={7} />
                    ) : (
                      data.length === 0 && (
                        <tr>
                          <td colSpan="7" className="text-center">
                            No history found
                          </td>
                        </tr>
                      )
                    )}

                    {data.map((row) => (
                      <tr key={row.id}>
                        <td>
                          <Link
                            to={`/t72-purchase/${row.purchase}`}
                            className="text-primary fw-bold"
                          >
                            {row.order_number}
                          </Link>
                        </td>
                        <td className="fw-bold">{row.item_name}</td>
                        <td>{Number(row.quantity)}</td>
                        <td>{row.unit}</td>
                        <td>{row.issued_by_name}</td>
                        <td>{row.received_by_name}</td>
                        <td>{row.issue_at}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {!isLoading && totals > 0 && (
                  <div className="d-flex justify-content-end p-3">
                    <Pagination
                      currentPage={params.page}
                      recordsPage={params.page_size}
                      dataLength={totals}
                      handlePagination={handlePagination}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Export Confirmation Modal */}
      <Modal
        show={showExportConfirm}
        onHide={() => setShowExportConfirm(false)}
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>Confirm Export</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <p>Are you sure you want to export the issued history?</p>
          {fromDate && toDate && (
            <p className="text-muted small">
              Date Range: {fromDate} to {toDate}
            </p>
          )}
        </Modal.Body>
        <Modal.Footer>
          <button
            className="btn btn-secondary"
            onClick={() => setShowExportConfirm(false)}
          >
            Cancel
          </button>
          <button
            className="btn btn-success"
            onClick={handleExport}
            disabled={exporting}
          >
            {exporting ? <>Exporting...</> : "Confirm Export"}
          </button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}
