import { useState, useEffect } from "react";
import { Modal } from "react-bootstrap";
import Select from "react-select";
import { issueT72, getT72Detail } from "../../../../services/T72Service";
import { searchEmployee } from "../../../../services/RackService";
import { toast } from "react-toastify";

export default function T72IssueModal({ show, onHide, issueData, reload }) {
  // issueData contains the T72 summary, but we need items
  const [items, setItems] = useState([]);
  const [employeeOptions, setEmployeeOptions] = useState([]);
  const [loadingItems, setLoadingItems] = useState(false);
  const [form, setForm] = useState({
    received_by: null, // Employee ID
    items: {}, // { itemId: quantity_to_issue }
  });

  const [errors, setErrors] = useState({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (show && issueData?.id) {
      fetchDetails(issueData.id);
      fetchEmployees();
      setForm({ received_by: null, items: {} });
      setErrors({});
    }
  }, [show, issueData]);

  const fetchDetails = async (id) => {
    setLoadingItems(true);
    try {
      const response = await getT72Detail(id);
      // Backend serializer needs to return items with available_quantity
      // Assuming GET T72 returns { ...t72, items: [...] }
      if (response.data && response.data.items) {
        // Only show items with available quantity > 0
        const availableItems = response.data.items.filter(
          (item) => parseFloat(item.available_quantity) > 0,
        );
        setItems(availableItems);
      } else {
        // Fallback if data structure is different
        setItems([]);
      }
    } catch (error) {
      console.error(error);
      toast.error("Failed to load items");
    } finally {
      setLoadingItems(false);
    }
  };

  const fetchEmployees = async () => {
    try {
      const response = await searchEmployee();
      setEmployeeOptions(response.data.data); // data.data based on RackService usage usually
    } catch (error) {
      console.error(error);
    }
  };

  const handleQtyChange = (itemId, val, max) => {
    let qty = val;
    const numVal = parseFloat(val);

    // If user enters val > max, clamp it
    if (!isNaN(numVal) && numVal > max) {
      qty = max;
      // Optionally show toast or hint? For now just clamp.
    }

    // Also prevent negative
    if (!isNaN(numVal) && numVal < 0) {
      qty = 0;
    }

    setForm((prev) => ({
      ...prev,
      items: {
        ...prev.items,
        [itemId]: qty,
      },
    }));
  };

  const handleEmployeeChange = (option) => {
    setForm((prev) => ({ ...prev, received_by: option ? option.value : null }));
    if (errors.received_by)
      setErrors((prev) => ({ ...prev, received_by: null }));
  };

  const validate = () => {
    const e = {};
    if (!form.received_by) e.received_by = "Required";

    let hasItems = false;
    Object.entries(form.items).forEach(([itemId, qty]) => {
      const q = parseFloat(qty);
      if (q > 0) hasItems = true;

      // Find item to check max
      const item = items.find(
        (i) => i.id === itemId || i.id === parseInt(itemId),
      );
      if (item && q > parseFloat(item.available_quantity)) {
        e[itemId] = `Max ${item.available_quantity}`;
      }
    });

    if (!hasItems) {
      toast.error("Please enter quantity for at least one item.");
      return false;
    }

    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const submit = async () => {
    if (!validate()) return;
    setSaving(true);

    // Construct payload
    // items: [{ id, quantity }]
    const itemsToIssue = Object.entries(form.items)
      .map(([id, qty]) => ({ id, quantity: qty }))
      .filter((i) => parseFloat(i.quantity) > 0);

    const payload = {
      received_by: form.received_by,
      items: itemsToIssue,
    };

    try {
      await issueT72(issueData.id, payload);
      toast.success("Items Issued Successfully");
      reload();
      onHide();
    } catch (error) {
      console.error(error);
      if (error.response && error.response.data) {
        toast.error(error.response.data.error || "Error issuing items");
      } else {
        toast.error("An error occurred");
      }
    } finally {
      setSaving(false);
    }
  };

  if (!show) return null;

  return (
    <Modal show={show} onHide={onHide} size="lg" backdrop="static">
      <div className="modal-content">
        <div className="modal-header bg-primary text-white">
          <h5 className="modal-title text-white">
            Issue Material - {issueData?.order_number}
          </h5>
          <button
            type="button"
            className="btn-close btn-close-white"
            onClick={onHide}
          ></button>
        </div>
        <div className="modal-body">
          <div className="row mb-4">
            <div className="col-md-6">
              <label className="form-label">
                Received By <span className="text-danger">*</span>
              </label>
              <Select
                options={employeeOptions}
                value={employeeOptions.find(
                  (e) => e.value === form.received_by,
                )}
                onChange={handleEmployeeChange}
                placeholder="Search Employee..."
                className={errors.received_by ? "is-invalid" : ""}
              />
              {errors.received_by && (
                <div className="invalid-feedback d-block">
                  {errors.received_by}
                </div>
              )}
            </div>
          </div>

          {loadingItems ? (
            <div className="text-center py-4">Loading Items...</div>
          ) : (
            <div className="table-responsive">
              <table className="table table-bordered align-middle">
                <thead className="table-light">
                  <tr>
                    <th>Item Name</th>
                    <th>Location</th>
                    <th>Available Qty</th>
                    <th width="20%">Issue Qty</th>
                  </tr>
                </thead>
                <tbody>
                  {items.map((item) => (
                    <tr
                      key={item.id}
                      className={`${form.items[item.id] > 0 ? "bg-success-light" : ""}`}
                    >
                      <td>{item.item_name}</td>
                      <td>{item.location}</td>
                      <td className="fw-bold text-success">
                        {item.available_quantity}
                      </td>
                      <td>
                        <input
                          type="number"
                          className={`form-control form-control-sm ${errors[item.id] ? "is-invalid" : ""}`}
                          min="0"
                          max={item.available_quantity}
                          disabled={parseFloat(item.available_quantity) <= 0}
                          value={form.items[item.id] || ""}
                          onChange={(e) =>
                            handleQtyChange(
                              item.id,
                              e.target.value,
                              item.available_quantity,
                            )
                          }
                          placeholder={
                            parseFloat(item.available_quantity) <= 0
                              ? "Empty"
                              : "Enter Qty"
                          }
                        />
                        {errors[item.id] && (
                          <div className="invalid-feedback">
                            {errors[item.id]}
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                  {items.length === 0 && (
                    <tr>
                      <td colSpan="6" className="text-center">
                        No items found
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onHide}>
            Cancel
          </button>
          <button
            className="btn btn-primary"
            onClick={submit}
            disabled={saving || loadingItems}
          >
            {saving ? (
              <>
                <span className="spinner-border spinner-border-sm me-1"></span>{" "}
                Issuing...
              </>
            ) : (
              "Confirm Issue"
            )}
          </button>
        </div>
      </div>
    </Modal>
  );
}
