// pages/T72ListPage.jsx
import { useEffect, useState } from "react";
import { getT72List, getT72Dashboard } from "../../../services/T72Service";
import T72FormModal from "./components/T72FormModal";
import DebounceSearchInput from "../../constant/DebounceSearchInput";
import Pagination from "../../constant/Pagination";
import TableLoaderEffect from "../../constant/TableLoader";
import { Link } from "react-router-dom";
import T72StatusBadge from "./components/T72StatusBadge";

export default function T72ListPage() {
  const [data, setData] = useState([]);
  const [totals, setTotals] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [dashboard, setDashboard] = useState({});
  const [show, setShow] = useState(false);
  const [editData, setEditData] = useState(null);
  const [params, setParams] = useState({
    page: 1,
    page_size: 10,
    query: "",
    status: "",
  });

  const handleStatusFilter = (status) => {
    // If clicking same status, clear filter (toggle). EXCEPT for "Total Orders" (status="") we always set to ""
    if (status === "" || params.status === status) {
      // Toggle off if same, unless it's the 'All' filter which remains blank
      const newStatus =
        status === "" && params.status === ""
          ? ""
          : params.status === status
            ? ""
            : status;

      const updatedParams = { ...params, status: newStatus, page: 1 };
      setParams(updatedParams);
      load72Data(updatedParams);
    } else {
      const updatedParams = { ...params, status, page: 1 };
      setParams(updatedParams);
      load72Data(updatedParams);
    }
  };

  const loadData = async () => {
    setIsLoading(true);
    const [dashRes, listRes] = await Promise.all([
      getT72Dashboard(),
      getT72List({ ...params }),
    ]);

    setData(listRes.data.data);
    setTotals(listRes.data.total);
    setDashboard(dashRes.data);
    setIsLoading(false);
  };

  const load72Data = async (updatedParams) => {
    setIsLoading(true);
    const listRes = await getT72List({ ...updatedParams });
    setData(listRes.data.data);
    setTotals(listRes.data.total);
    setIsLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleSearchChange = (value) => {
    const updatedParams = { ...params, query: value, page: 1 };
    setParams(updatedParams);
    load72Data(updatedParams);
  };

  const handlePagination = (page) => {
    const newPage = page.selected + 1;
    const updatedParams = { ...params, page: newPage };
    setParams(updatedParams);
    load72Data(updatedParams);
  };

  const dashboardCards = [
    {
      title: "Total Orders",
      value: dashboard?.total_orders || 0,
      icon: "fa-clipboard-list",
      color: "primary",
      status: "",
    },
    {
      title: "Received",
      value: dashboard?.received || 0,
      icon: "fa-box-open",
      color: "success",
      status: "RECEIVED",
    },
    {
      title: "Partial Issued",
      value: dashboard?.partial_issued || 0,
      icon: "fa-hourglass-half",
      color: "warning",
      status: "PARTIALLY_ISSUED",
    },
    {
      title: "Total Issued",
      value: dashboard?.issued || 0,
      icon: "fa-share-from-square",
      color: "danger",
      status: "ISSUED",
    },
  ];

  return (
    <div className="container-fluid">
      <div className="row">
        <div className="col-xl-12">
          <div className="row">
            {isLoading
              ? [...Array(4)].map((_, i) => (
                  <div className="col-xl-3 col-sm-6" key={i}>
                    <div className="card">
                      <div className="card-body d-flex align-items-center justify-content-between">
                        <div
                          className="skeleton-box rounded-circle"
                          style={{ width: "60px", height: "60px" }}
                        ></div>
                        <div className="text-end">
                          <div
                            className="skeleton-text mb-2"
                            style={{ width: "80px", height: "20px" }}
                          ></div>
                          <div
                            className="skeleton-text"
                            style={{ width: "40px", height: "30px" }}
                          ></div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              : dashboardCards.map((card, index) => (
                  <div className="col-xl-3 col-sm-6" key={index}>
                    <div
                      className={`card ${
                        params.status === card.status
                          ? `border border-2 border-${card.color}`
                          : ""
                      }`}
                      onClick={() => handleStatusFilter(card.status)}
                      style={{ cursor: "pointer" }}
                    >
                      <div className="card-body d-flex align-items-center justify-content-between">
                        <div
                          className={`d-flex align-items-center justify-content-center rounded-circle shadow shadow-sm bg-${card.color}-light text-${card.color}`}
                          style={{
                            width: "60px",
                            height: "60px",
                            flexShrink: 0,
                          }}
                        >
                          <i className={`fa-solid ${card.icon} fs-2`}></i>
                        </div>

                        <div className="text-end">
                          <p className="fs-14 mb-1 text-muted">{card.title}</p>
                          <span className={`fs-20 fw-bold text-dark`}>
                            {Number(card.value).toLocaleString()}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
          </div>

          <div className="card">
            <div className="card-body p-0">
              <div className="tbl-caption d-flex justify-content-between text-wrap align-items-center p-3">
                <h4 className="mb-0">T-72 List</h4>

                <div className="d-flex align-items-center flex-wrap gap-3">
                  <Link
                    to="/t72-issued-history"
                    className="btn btn-outline-secondary"
                  >
                    <i className="fa-solid fa-clock-rotate-left me-1"></i>{" "}
                    History
                  </Link>
                  <div className="form-group">
                    <DebounceSearchInput
                      handleSearchChange={handleSearchChange}
                    />
                  </div>

                  <>
                    <button
                      className="btn btn-primary"
                      data-bs-toggle="offcanvas"
                      onClick={() => {
                        setEditData(null);
                        setShow(true);
                      }}
                    >
                      <i className="fa-solid fa-plus me-1"></i> Add T-72
                    </button>
                  </>
                </div>
              </div>

              <div className="table-responsive active-projects style-1 ItemsCheckboxSec shorting">
                <div
                  id="employee-tbl_wrapper"
                  className="dataTables_wrapper no-footer"
                >
                  <table
                    id="empoloyees-tblwrapper"
                    className="table ItemsCheckboxSec dataTable no-footer mb-0"
                  >
                    <thead>
                      <tr>
                        <th>Order No</th>
                        <th>Challan No</th>
                        <th>Daybook No</th>
                        <th>Receive Date</th>
                        <th>Status</th>
                        <th>Items</th>
                      </tr>
                    </thead>
                    <tbody>
                      {isLoading ? (
                        <TableLoaderEffect colLength={6} />
                      ) : (
                        data.length === 0 && (
                          <tr>
                            <td colSpan="6" className="text-center">
                              No records found
                            </td>
                          </tr>
                        )
                      )}

                      {data.map((row, idx) => (
                        <tr key={row.id}>
                          <td>
                            <Link
                              to={`/t72-purchase/${row.id}`}
                              className="text-primary fw-bold"
                            >
                              {row.order_number}
                            </Link>
                          </td>
                          <td>{row.challan_number}</td>
                          <td>{row.daybook_number}</td>
                          <td>{row.receive_date}</td>
                          <td>
                            <T72StatusBadge status={row.status} />
                          </td>
                          <td title={row.item_names}>
                            {row.item_names && row.item_names.length > 50
                              ? row.item_names.substring(0, 50) + "..."
                              : row.item_names}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {isLoading ? (
                    <div style={{ height: "4rem" }}></div>
                  ) : (
                    <Pagination
                      currentPage={params.page}
                      recordsPage={params.page_size}
                      dataLength={totals}
                      handlePagination={handlePagination}
                    />
                  )}
                </div>
              </div>

              <T72FormModal
                show={show}
                onHide={() => setShow(false)}
                editData={editData}
                reload={loadData}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
