// components/T72FormModal.jsx
import { useState, useEffect } from "react";
import {
  createT72,
  updateT72,
  searchUsers,
} from "../../../../services/T72Service";
import Select from "react-select";
import { Modal } from "react-bootstrap";
import { toast } from "react-toastify";

export default function T72FormModal({ show, onHide, editData, reload }) {
  const emptyItem = { item_name: "", quantity: "", unit: "", location: "" };
  const [userOptions, setUserOptions] = useState([]);
  const [isUserFetching, setIsUserFetching] = useState(false);

  const [form, setForm] = useState({
    receive_date: "",
    daybook_number: "",
    order_number: "",
    challan_number: "",
    party_name: "",
    used_area: "",
    authorized_by: null,
    received_by: null,
    remarks: "",
    is_issued: false,
    issued_date: "",
    issued_by: null,
    items: [emptyItem],
  });
  const [errors, setErrors] = useState({});
  const [saving, setSaving] = useState(false);

  const fetchUsers = async () => {
    setIsUserFetching(true);
    try {
      const response = await searchUsers();
      setUserOptions(response.data.data);
    } catch (error) {
      console.error(error);
    } finally {
      setIsUserFetching(false);
    }
  };

  useEffect(() => {
    if (show) {
      if (editData) {
        const { authorized_by, received_by, issued_by, ...rest } = editData;
        setForm({
          ...rest,
          authorized_by: authorized_by ? authorized_by.value : null,
          received_by: received_by ? received_by.value : null,
          is_issued: issued_by ? true : false,
          issued_by: issued_by ? issued_by.value : null,
          items:
            editData.items && editData.items.length > 0
              ? editData.items
              : [emptyItem],
        });
      } else {
        setForm({
          receive_date: new Date().toISOString().split("T")[0],
          party_name: "",
          remarks: "",
          daybook_number: "",
          order_number: "",
          challan_number: "",
          used_area: "",
          authorized_by: null,
          received_by: null,
          is_issued: false,
          issued_date: "",
          issued_by: null,
          items: [emptyItem],
        });
      }
      setErrors({});
      fetchUsers();
    } else {
      setForm({
        receive_date: new Date().toISOString().split("T")[0],
        party_name: "",
        remarks: "",
        daybook_number: "",
        order_number: "",
        challan_number: "",
        used_area: "",
        authorized_by: null,
        received_by: null,
        is_issued: false,
        issued_date: "",
        issued_by: null,
        items: [emptyItem],
      });
      setErrors({}); // Clear errors when the modal is closed
      setUserOptions([]);
      setIsUserFetching(false);
    }
  }, [show, editData]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) setErrors((prev) => ({ ...prev, [name]: null }));
  };

  const handleSelectChange = (data, name) => {
    setForm((prev) => ({ ...prev, [name]: data ? data.value : "" }));
    if (errors[name]) setErrors((prev) => ({ ...prev, [name]: null }));
  };

  const handleItemChange = (index, e) => {
    const { name, value } = e.target;
    const newItems = [...form.items];
    newItems[index] = { ...newItems[index], [name]: value };
    setForm((prev) => ({ ...prev, items: newItems }));

    // Clear specific item error if exists
    if (
      errors.itemsList &&
      errors.itemsList[index] &&
      errors.itemsList[index][name]
    ) {
      const newErrorsList = [...errors.itemsList];
      if (newErrorsList[index]) {
        newErrorsList[index] = { ...newErrorsList[index], [name]: null };
        // Cleanup if empty
        // if (Object.keys(newErrorsList[index]).every(k => !newErrorsList[index][k])) newErrorsList[index] = null;
      }
      setErrors((prev) => ({ ...prev, itemsList: newErrorsList }));
    }

    // Also clear global duplicate error msg if typing
    if (errors.items) {
      setErrors((prev) => ({ ...prev, items: null }));
    }
  };

  const addItem = () => {
    setForm((prev) => ({ ...prev, items: [...prev.items, emptyItem] }));
  };

  const removeItem = (index) => {
    if (form.items.length <= 1) return;
    const newItems = form.items.filter((_, i) => i !== index);
    setForm((prev) => ({ ...prev, items: newItems }));
  };

  const validate = () => {
    let e = {};
    if (!form.receive_date) e.receive_date = "Required";
    if (!form.party_name) e.party_name = "Required";
    if (!form.daybook_number) e.daybook_number = "Required";
    if (!form.order_number) e.order_number = "Required";
    if (!form.challan_number) e.challan_number = "Required";
    if (!form.party_name) e.party_name = "Required";
    if (!form.used_area) e.used_area = "Required";
    if (!form.authorized_by) e.authorized_by = "Required";

    const today = new Date().toISOString().split("T")[0];
    if (form.receive_date && form.receive_date > today) {
      e.receive_date = "Future date not allowed";
    }

    if (!form.items || form.items.length === 0) {
      e.items = "Add at least one item";
    } else {
      // Find duplicate names
      const lowerNames = form.items.map((i) =>
        (i.item_name || "").trim().toLowerCase(),
      );
      const duplicates = lowerNames.filter(
        (name, index) => name && lowerNames.indexOf(name) !== index,
      );

      if (duplicates.length > 0) {
        e.items = "Duplicate items found. Please remove or rename them.";
      }

      const itemErrors = form.items.map((item, idx) => {
        const err = {};
        if (!item.item_name) err.item_name = true;
        if (item.quantity === "" || item.quantity === null) err.quantity = true; // explicitly check empty
        if (!item.unit) err.unit = true;
        if (!item.location) err.location = true;

        // Mark duplicate
        const name = (item.item_name || "").trim().toLowerCase();
        if (name && duplicates.includes(name)) {
          err.item_name = "Duplicate";
        }

        return Object.keys(err).length > 0 ? err : null;
      });
      if (itemErrors.some((err) => err !== null)) e.itemsList = itemErrors;
    }
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const submit = async () => {
    if (!validate()) {
      toast.error("Please correct errors in the form");
      return;
    }
    setSaving(true);

    const payload = { ...form };
    // Convert empty strings to null for backend
    if (!payload.receive_date) payload.receive_date = null;
    if (!payload.daybook_number) payload.daybook_number = null;

    // Optional/Nullable fields
    if (payload.authorized_by === "") payload.authorized_by = null;

    // Cleanup removed fields just in case
    delete payload.is_issued;
    delete payload.issued_by;
    delete payload.issued_date;
    delete payload.received_by;

    try {
      editData
        ? await updateT72(editData.id, payload)
        : await createT72(payload);
      toast.success("T-72 Saved Successfully");
      reload();
      onHide();
    } catch (error) {
      console.error(error);
      if (error.response && error.response.data) {
        const backendErrors = error.response.data;
        const formattedErrors = {};
        Object.keys(backendErrors).forEach((key) => {
          formattedErrors[key] = Array.isArray(backendErrors[key])
            ? backendErrors[key][0]
            : backendErrors[key];
        });
        setErrors(formattedErrors);
        toast.error("Please correct the errors in the form");
      } else {
        toast.error("An error occurred while saving.");
      }
    } finally {
      setSaving(false);
    }
  };

  if (!show) return null;

  return (
    <Modal
      className="modal fade"
      id="exampleModal3"
      show={show}
      onHide={onHide}
      fullscreen={true}
      backdrop="static"
      keyboard={false}
    >
      <div className="modal-content">
        <div className="modal-header bg-primary text-white">
          <h5 className="modal-title text-white">
            {editData ? "Edit T-72" : "New T-72 Entry"}
          </h5>
          <button
            type="button"
            className="btn-close btn-close-white"
            onClick={onHide}
          ></button>
        </div>
        <div className="modal-body">
          {/* Header Fields */}
          <div className="row">
            <div className="col-md-3 mb-3">
              <label className="form-label">
                Receive Date <span className="text-danger">*</span>
              </label>
              <input
                type="date"
                className={`form-control ${
                  errors.receive_date ? "is-invalid" : ""
                }`}
                name="receive_date"
                value={form.receive_date}
                onChange={handleChange}
              />
              {errors.receive_date && (
                <div className="invalid-feedback">{errors.receive_date}</div>
              )}
            </div>
            <div className="col-md-3 mb-3">
              <label className="form-label">
                Daybook No <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                className={`form-control ${
                  errors.daybook_number ? "is-invalid" : ""
                }`}
                name="daybook_number"
                placeholder="Enter Daybook No"
                value={form.daybook_number}
                onChange={handleChange}
              />
              {errors.daybook_number && (
                <div className="invalid-feedback">{errors.daybook_number}</div>
              )}
            </div>
            <div className="col-md-3 mb-3">
              <label className="form-label">
                Order No <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                className={`form-control ${
                  errors.order_number ? "is-invalid" : ""
                }`}
                name="order_number"
                placeholder="Enter Order No"
                value={form.order_number}
                onChange={handleChange}
              />
              {errors.order_number && (
                <div className="invalid-feedback">{errors.order_number}</div>
              )}
            </div>
            <div className="col-md-3 mb-3">
              <label className="form-label">
                Challan No <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                className={`form-control ${
                  errors.challan_number ? "is-invalid" : ""
                }`}
                name="challan_number"
                placeholder="Enter Challan No"
                value={form.challan_number || ""}
                onChange={handleChange}
              />
              {errors.challan_number && (
                <div className="invalid-feedback">{errors.challan_number}</div>
              )}
            </div>

            <div className="col-md-3 mb-3">
              <label className="form-label">
                Party Name <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                className={`form-control ${
                  errors.party_name ? "is-invalid" : ""
                }`}
                name="party_name"
                placeholder="Enter Party Name"
                value={form.party_name}
                onChange={handleChange}
              />
              {errors.party_name && (
                <div className="invalid-feedback">{errors.party_name}</div>
              )}
            </div>

            <div className="col-md-3 mb-3">
              <label className="form-label">
                Used Area <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                className={`form-control ${
                  errors.used_area ? "is-invalid" : ""
                }`}
                name="used_area"
                placeholder="Enter Used Area"
                value={form.used_area || ""}
                onChange={handleChange}
              />
              {errors.used_area && (
                <div className="invalid-feedback">{errors.used_area}</div>
              )}
            </div>
            <div className="col-md-3 mb-3">
              <label className="form-label">
                Authorized By <span className="text-danger">*</span>
              </label>
              <Select
                value={
                  userOptions.find(
                    (user) => user.value === form.authorized_by,
                  ) || null
                }
                isDisabled={isUserFetching}
                onChange={(data) => handleSelectChange(data, "authorized_by")}
                placeholder={"Select Authorized By"}
                isClearable={false}
                isLoading={isUserFetching}
                options={userOptions}
                id={"authorized_by"}
                name={"authorized_by"}
                className={`react-select ${
                  errors.authorized_by ? "is-invalid" : ""
                }`}
                classNamePrefix="select"
              />
              {errors.authorized_by && (
                <div className="invalid-feedback">{errors.authorized_by}</div>
              )}
            </div>
            <div className="col-md-3 mb-3">
              <label className="form-label">Remarks</label>
              <textarea
                className="form-control"
                name="remarks"
                placeholder="Enter Remarks"
                value={form.remarks || ""}
                onChange={handleChange}
              />
            </div>
          </div>
          <hr />

          {/* Items Section */}
          <div className="d-flex justify-content-between align-items-center mb-2">
            <h5 className="mb-0">Items</h5>
            <button className="btn btn-sm btn-primary" onClick={addItem}>
              <i className="fa fa-plus me-1"></i> Add Item
            </button>
          </div>

          {errors.items && (
            <div className="alert alert-danger py-1 px-2">{errors.items}</div>
          )}

          <div className="table-responsive">
            <table className="table table-bordered table-striped">
              <thead className="table-light">
                <tr>
                  <th width="5%">SL No</th>
                  <th width="35%">
                    Item Name <span className="text-danger">*</span>
                  </th>
                  <th width="15%">
                    Quantity <span className="text-danger">*</span>
                  </th>
                  <th width="15%">
                    Unit <span className="text-danger">*</span>
                  </th>
                  <th width="20%">
                    Location <span className="text-danger">*</span>
                  </th>
                  <th width="10%">Action</th>
                </tr>
              </thead>
              <tbody>
                {form.items.map((item, idx) => {
                  const itemError = errors.itemsList
                    ? errors.itemsList[idx]
                    : null;
                  return (
                    <tr key={idx}>
                      <td className="text-center align-middle">{idx + 1}</td>
                      <td>
                        <input
                          type="text"
                          className={`form-control form-control-sm ${
                            itemError?.item_name ? "is-invalid" : ""
                          }`}
                          name="item_name"
                          placeholder="Item Name"
                          autoFocus={idx === form.items.length - 1}
                          value={item.item_name}
                          onChange={(e) => handleItemChange(idx, e)}
                        />
                        {itemError?.item_name &&
                          itemError.item_name !== true && (
                            <div
                              className="invalid-feedback"
                              style={{ display: "block", margin: 0 }}
                            >
                              {itemError.item_name}
                            </div>
                          )}
                      </td>
                      <td>
                        <input
                          type="number"
                          className={`form-control form-control-sm ${
                            itemError?.quantity ? "is-invalid" : ""
                          }`}
                          name="quantity"
                          placeholder="Qty"
                          value={item.quantity}
                          onChange={(e) => handleItemChange(idx, e)}
                        />
                      </td>
                      <td>
                        <input
                          type="text"
                          className={`form-control form-control-sm ${
                            itemError?.unit ? "is-invalid" : ""
                          }`}
                          name="unit"
                          placeholder="Unit"
                          value={item.unit}
                          onChange={(e) => handleItemChange(idx, e)}
                        />
                      </td>
                      <td>
                        <input
                          type="text"
                          className={`form-control form-control-sm ${
                            itemError?.location ? "is-invalid" : ""
                          }`}
                          name="location"
                          placeholder="Location"
                          value={item.location}
                          onChange={(e) => handleItemChange(idx, e)}
                        />
                      </td>
                      <td className="text-center align-middle">
                        {form.items.length > 1 && (
                          <button
                            className="btn btn-danger btn-xs"
                            onClick={() => removeItem(idx)}
                            title="Remove Item"
                          >
                            <i className="fa fa-trash"></i>
                          </button>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onHide}>
            Close
          </button>
          <button
            className="btn btn-success"
            onClick={submit}
            disabled={saving}
          >
            {saving ? (
              <>
                <span className="spinner-border spinner-border-sm me-1"></span>{" "}
                Saving...
              </>
            ) : (
              "Save Changes"
            )}
          </button>
        </div>
      </div>
    </Modal>
  );
}
